from ortools.linear_solver import pywraplp
import json

def main():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        print(json.dumps({
            "diagnostic_terminal_sequence": [],
            "total_service_time": -1
        }))
        return

    INF = solver.infinity()

    V = [1, 2, 3, 4, 5]
    B = [1, 2]

    p1 = 1
    p2 = {1: 15, 2: 21, 3: 31, 4: 15, 5: 32}
    p3 = {1: 43, 2: 30, 3: 34, 4: 43, 5: 45}

    M = 1000

    x = {}
    y = {}
    z = {}
    b_var = {}
    seq = {}
    bay_seq = {}
    same_bay = {}
    Cmax = solver.NumVar(0, INF, "Cmax")

    for i in V:
        x[i] = solver.NumVar(0, INF, f"x[{i}]")
        y[i] = solver.NumVar(0, INF, f"y[{i}]")
        z[i] = solver.NumVar(0, INF, f"z[{i}]")
        b_var[i] = solver.IntVar(1, 2, f"b[{i}]")

    for i in V:
        seq[i] = {}
        bay_seq[i] = {}
        same_bay[i] = {}
        for j in V:
            if i != j:
                seq[i][j] = solver.BoolVar(f"seq[{i}][{j}]")
                bay_seq[i][j] = solver.BoolVar(f"bay_seq[{i}][{j}]")
                same_bay[i][j] = solver.BoolVar(f"same_bay[{i}][{j}]")

    for i in V:
        solver.Add(x[i] + p1 <= y[i], f"phase1_to_2[{i}]")
        solver.Add(y[i] + p2[i] <= z[i], f"phase2_to_3[{i}]")

    for i in V:
        for j in V:
            if i < j:
                solver.Add(seq[i][j] + seq[j][i] == 1, f"seq_exclusive[{i}][{j}]")

                solver.Add(y[i] + p2[i] <= y[j] + M * (1 - seq[i][j]), 
                          f"seq_order_ij[{i}][{j}]")

                solver.Add(y[j] + p2[j] <= y[i] + M * (1 - seq[j][i]), 
                          f"seq_order_ji[{i}][{j}]")

    for i in V:
        for j in V:
            if i < j:

                solver.Add(b_var[i] - b_var[j] <= M * (1 - same_bay[i][j]), 
                          f"same_bay_upper1[{i}][{j}]")
                solver.Add(b_var[j] - b_var[i] <= M * (1 - same_bay[i][j]), 
                          f"same_bay_upper2[{i}][{j}]")
                solver.Add(b_var[i] - b_var[j] >= -M * same_bay[i][j], 
                          f"same_bay_lower1[{i}][{j}]")
                solver.Add(b_var[j] - b_var[i] >= -M * same_bay[i][j], 
                          f"same_bay_lower2[{i}][{j}]")

    for i in V:
        for j in V:
            if i < j:
                solver.Add(x[i] + p1 <= x[j] + M * (1 - bay_seq[i][j]) + M * (1 - same_bay[i][j]),
                          f"phase1_no_overlap_ij[{i}][{j}]")
                solver.Add(x[j] + p1 <= x[i] + M * (1 - bay_seq[j][i]) + M * (1 - same_bay[i][j]),
                          f"phase1_no_overlap_ji[{i}][{j}]")

                solver.Add(z[i] + p3[i] <= z[j] + M * (1 - bay_seq[i][j]) + M * (1 - same_bay[i][j]),
                          f"phase3_no_overlap_ij[{i}][{j}]")
                solver.Add(z[j] + p3[j] <= z[i] + M * (1 - bay_seq[j][i]) + M * (1 - same_bay[i][j]),
                          f"phase3_no_overlap_ji[{i}][{j}]")

                solver.Add(x[i] + p1 <= z[j] + M * (1 - bay_seq[i][j]) + M * (1 - same_bay[i][j]),
                          f"phase1_phase3_no_overlap_ij[{i}][{j}]")
                solver.Add(z[i] + p3[i] <= x[j] + M * (1 - bay_seq[j][i]) + M * (1 - same_bay[i][j]),
                          f"phase3_phase1_no_overlap_ji[{i}][{j}]")

                solver.Add(bay_seq[i][j] + bay_seq[j][i] >= same_bay[i][j],
                          f"bay_seq_consistency[{i}][{j}]")
                solver.Add(bay_seq[i][j] + bay_seq[j][i] <= 1,
                          f"bay_seq_consistency2[{i}][{j}]")

    for i in V:
        solver.Add(z[i] + p3[i] <= Cmax, f"makespan_def[{i}]")

    solver.Minimize(Cmax)

    solver.SetTimeLimit(30000)
    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        seq_order = []
        remaining = set(V)

        for i in V:
            is_first = True
            for j in V:
                if i != j and seq[j][i].solution_value() > 0.5:
                    is_first = False
                    break
            if is_first:
                seq_order.append(i)
                remaining.remove(i)
                break

        while remaining:
            last = seq_order[-1]
            found = False
            for i in remaining:
                if seq[last][i].solution_value() > 0.5:
                    seq_order.append(i)
                    remaining.remove(i)
                    found = True
                    break
            if not found:
                seq_order.extend(sorted(remaining))
                break

        print(json.dumps({
            "diagnostic_terminal_sequence": seq_order,
            "total_service_time": int(round(Cmax.solution_value()))
        }))
    else:
        print(json.dumps({
            "diagnostic_terminal_sequence": [],
            "total_service_time": -1
        }))

if __name__ == "__main__":
    main()
